for(const b of strideVenue.barns)labels.push({p:[b.x,4,b.z],text:b.name+' · B TO COLLECT',color:'#fff3d7',size:12});for(const f of strideVenue.fields)labels.push({p:[f.x,2,f.z],text:f.name,color:'#fff3d7',size:12});if(round){const f=fences[round.next];if(f){const p=[f.x,3.6+Math.sin(clock*3)*.2,f.z];labels.push({p,text:`↓  FENCE ${f.id}`,color:'#f4f1b4',size:15});}}
if(gpu){try{gpu.render(staticFaces,faces.slice(staticFaces.length),cam,width,height);}catch(e){gpu=null;window.strideGpu=false;gpuCanvas.hidden=true;render();return;}}else{let draw=[];for(const f of faces){let pts=f.v.map(project);if(pts.some(p=>p.d<.35))pts=clipNear(f.v).map(project);if(pts.length>=3){const minX=Math.min(...pts.map(p=>p.x)),maxX=Math.max(...pts.map(p=>p.x)),minY=Math.min(...pts.map(p=>p.y)),maxY=Math.max(...pts.map(p=>p.y));if(maxX<0||minX>width||maxY<0||minY>height)continue;draw.push({pts,c:f.c,character:f.character,layer:f.ground?0:f.shadow?1:2,d:pts.reduce((s,p)=>s+p.d,0)/pts.length});}}
draw.sort((a,b)=>a.layer-b.layer||b.d-a.d);for(const f of draw){if(f.character){const cx=f.pts.reduce((s,p)=>s+p.x,0)/f.pts.length,cy=f.pts.reduce((s,p)=>s+p.y,0)/f.pts.length;for(const p of f.pts){let dx=p.x-cx,dy=p.y-cy,len=Math.hypot(dx,dy)||1;p.x+=dx/len*.3;p.y+=dy/len*.3;}}ctx.beginPath();ctx.moveTo(f.pts[0].x,f.pts[0].y);for(let i=1;i<f.pts.length;i++)ctx.lineTo(f.pts[i].x,f.pts[i].y);ctx.closePath();ctx.fillStyle=f.c;ctx.fill();}
}for(const l of labels){const p=project(l.p);if(p.d>1&&p.d<95&&p.x>0&&p.x<width){ctx.font=`600 ${clamp(l.size*22/p.d,8,l.size)}px system-ui`;ctx.textAlign='center';ctx.fillStyle='#18352980';let tw=ctx.measureText(l.text).width;ctx.fillRect(p.x-tw/2-5,p.y-13,tw+10,19);ctx.fillStyle=l.color;ctx.fillText(l.text,p.x,p.y);}}
